insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('11897328-8f7e-45a0-a2e8-fde69bdf9bc8', 'aefafd45-e8ca-4bef-88aa-bb1d83fe4e36', $$bron 1: Bartolomé de las Casas over het stamhoofd Hatuey (1552)$$,
   $$geschiedenis-havo-2021-iii-ontdekkers-en-hervormers-bron1.png$$,
   $$bron 1 In 1552 publiceert de Spaanse priester Bartolomé de las Casas een boek over de verovering van Amerika door de Spanjaarden. Hierin schrijft hij over Hatuey, een stamhoofd uit Cuba:
Dit stamhoofd kende de Spanjaarden en hun werkwijze maar al te goed. Hij vluchtte weg zodra ze op het eiland Cuba aankwamen en verzette zich alleen gewapenderhand als hij ze tegenkwam. Uiteindelijk werd hij gevangengenomen. Hoewel zijn enige misdaad was dat hij had geprobeerd te ontsnappen uit de klauwen van deze wrede en gewelddadige mannen omdat hij wel begreep dat ze erop uit waren hem te doden en dat, als hij zich niet verdedigde, ze hem en zijn volk de dood in zouden jagen. Toch spraken de Spanjaarden het vonnis uit dat hij levend verbrand moest worden. Toen hij was vastgebonden op de brandstapel kwam er een franciscaner monnik, een heilige man, die hem – in de beperkte tijd die de beulen hem gunden – vertelde over God en over ons christelijke geloof. Dit alles was nieuw voor Hatuey. De monnik vertelde dat, als hij dit allemaal zou gaan geloven, hij naar de hemel zou gaan. Als hij dit niet zou geloven, dan zou hij naar de hel gaan, waar eeuwigdurende pijn en kwelling waren. Hatuey dacht kort na en vroeg de monnik toen of christenen ook naar de hemel gingen. De monnik bevestigde dat dit voor de goede christenen zo was. Hatuey zei toen, zonder er verder over na te denken, dat hij liever naar de hel ging, om er zeker van te zijn dat hij zulke wrede mensen nooit meer zou tegenkomen.$$, 'inline'),
  ('82c7b2a6-ded9-4862-8f4c-1bc64715d2c8', 'aefafd45-e8ca-4bef-88aa-bb1d83fe4e36', $$bron 5: foto van Jacob Riis van een arbeidster in New York (1890)$$,
   $$geschiedenis-havo-2021-iii-ontdekkers-en-hervormers-bron5.png$$,
   $$bron 5 De Amerikaanse fotograaf Jacob Riis (1849-1914) houdt lezingen over de woonomstandigheden in arbeiderswijken in Amerikaanse steden. Hierdoor worden veel mensen zich ervan bewust hoe een groot deel van de arbeiders woont. In 1890 publiceert Riis zijn boek How the other half lives (Hoe de andere helft leeft), waarin onder meer deze foto staat van een arbeidster in New York in haar woning:
[Afbeelding] Foto: een vrouw zit in een kale, donkere kamer tussen tonnen, zakken, emmers en een ladder, met een bundel op schoot.$$, 'inline'),
  ('a83585c2-6046-4a65-8b15-652ef82ee8a9', '60071ab0-b960-4375-9998-9e25dd23c981', $$twee standpunten in het Amerikaanse Congres over de slavernij (1790)$$,
   $$geschiedenis-havo-2021-iii-het-britse-rijk-context1.png$$,
   $$In 1790 werd in het Amerikaanse Congres (parlement) gediscussieerd over de slavernij. Twee standpunten in het debat:
1 De slavernij is in strijd met de opvatting dat een mens geen bezit mag zijn van een ander mens.
2 Het congres kan de slavernij in een staat niet verbieden.$$, 'inline'),
  ('1059ad96-0463-41a9-9600-5a0270a2ca28', '60071ab0-b960-4375-9998-9e25dd23c981', $$bron 3: verzoekschrift van textielfabrikanten uit Glasgow (1789)$$,
   $$geschiedenis-havo-2021-iii-het-britse-rijk-bron3.png$$,
   $$bron 3 In 1789 sturen 103 textielfabrikanten uit de omgeving van Glasgow een verzoekschrift aan de Britse minister van Financiën, waarin zij onder andere het volgende schrijven:
Dat de rekestranten1) die zich tot u wenden al vroeg zijn begonnen Britse mousseline2) te fabriceren en in de voorbije jaren grote vooruitgang hebben geboekt bij het ontwikkelen en verbeteren van deze waardevolle bedrijfstak (…). Dat de machinekracht die in deze bedrijven wordt ingezet en de nieuwe fabrieksgebouwen die de rekestranten door toegenomen werkzaamheden hebben kunnen inrichten, leidt tot een overvloed aan artikelen die niet door binnenlandse consumptie kunnen worden gebruikt en daarom wordt een toename van de verkoop in het buitenland een onvermijdelijke noodzaak om de machines in bedrijf te houden.
noot 1 personen die een verzoekschrift (rekest) indienen noot 2 soort textiel$$, 'inline'),
  ('24a23bd0-0c97-4b73-aac4-ab434c8b373e', '23ccd0cb-5ceb-45d0-a6f1-d7c895df2f50', $$bron 2: arts IJsbrand van Diemerbroeck over zijn onderzoek naar de pest (1635-1637)$$,
   $$geschiedenis-havo-2021-iii-regenten-en-vorsten-bron2.png$$,
   $$bron 2 IJsbrand van Diemerbroeck is arts in Nijmegen tijdens de pestepidemie van 1635 tot 1637. Hij publiceert een boek over de pest, waarin hij schrijft:
[Ik doe dit] eens te meer, omdat tal van vooraanstaande medici, afgeschrikt door de vrees voor een dodelijke besmetting, hebben afgezien van een diepergaand onderzoek naar de vele zaken waarmee men bij de pest van alle dingen het meest rekening moet houden. Vandaar dat ze het verhaal van de pest niet precies genoeg hebben uiteengezet. Ze hebben allerlei nuttige waarnemingen overgeleverd, maar daar intussen andere aan toegevoegd die niet van hen zelf waren. (…) [De lezer zal ook merken dat ik] wat dit betreft de meeste dingen heel anders ga uitleggen dan vele anderen voorheen gedaan hebben en dat ik die dingen deels via glasheldere redeneringen ga demonstreren, maar deels ook ga bevestigen via ervaringen, deels van mijzelf, deels van andere zeer geleerde mannen, zowel uit heden als verleden.$$, 'inline'),
  ('f3b7be70-c9aa-4dd2-b925-8dc934ea262c', 'b97e7a7d-188a-43b5-a00a-b70f29451728', $$bron 7: Brits pamflet boven de Duitse linies afgeworpen (juli 1918)$$,
   $$geschiedenis-havo-2021-iii-tijd-van-wereldoorlogen-bron7.png$$,
   $$bron 7 Brits pamflet uit juli 1918 waarvan 50.000 exemplaren boven de Duitse linies zijn afgeworpen met behulp van een luchtballon:
[Afbeelding] Pamflet met twee tekeningen: bij het jaartal 1914 trekken ezels een wagen met Germania en een officier, voortgedreven met een wortel; bij 1918 trekken uitgeputte ezels een gammele wagen.
Vertaling van de bijschriften: Op de ezels staat: het Duitse volk Bij de vrouwen op de wagens staat: Germania (Duitsland) Op de wortel bij 1914 staat: overwinning Op de wortel bij 1918 staat: schijnoverwinning$$, 'inline'),
  ('32b5918f-a5aa-4b1c-938b-2706c8441cdd', 'b97e7a7d-188a-43b5-a00a-b70f29451728', $$bron 9: foto van schuilende burgers in een keldergewelf in Nijmegen (1944)$$,
   $$geschiedenis-havo-2021-iii-tijd-van-wereldoorlogen-bron9.png$$,
   $$bron 9 Op 6 oktober 1944 wordt een foto gemaakt van schuilende burgers in een oud keldergewelf in Nijmegen:
[Afbeelding] Foto: een grote groep burgers zit en ligt dicht op elkaar met dekens en bedden in een gewelfde kelder.$$, 'inline'),
  ('facf2958-70a5-4953-87e2-6a183dcf83c8', 'e717feff-31d3-46d3-b474-ae8e4442055c', $$bron 4: betoog van Thomas Babington Macaulay tegen de kiesrechtpetitie (1842)$$,
   $$geschiedenis-havo-2021-iii-burgers-en-stoommachines-bron4.png$$,
   $$bron 4 In 1842 wordt in Groot-Brittannië in het parlement een volkspetitie ingediend om het kiesrecht uit te breiden. De Britse politicus Thomas Babington Macaulay houdt in het parlement een betoog tegen de petitie. Enkele gedeelten uit zijn betoog:
Stel je een goedbedoelende, hardwerkende monteur voor, liefdevol gehecht aan zijn vrouw en kinderen. Slechte tijden komen. Hij ziet de vrouw van wie hij houdt elke dag dunner en bleker worden. Zijn kleintjes roepen om brood en hij heeft niemand om hun dat te geven. Dan komen de ophitsers en verleiders die hem vertellen dat er meer dan genoeg is voor iedereen; en dat hij te weinig heeft, omdat de rijke heren, bankiers, fabrikanten en winkeliers te veel hebben. Is het dan vreemd dat de arme man misleid wordt en een dergelijke petitie gretig ondertekent? (…) Onze eerlijke werkende man heeft geen opleiding ontvangen. Hij kan niet begrijpen dat de problemen die hij nu heeft, vele malen erger zullen worden als er ook maar een maand van plunderingen en chaos zou zijn. Maar u zegt, het is niet de schuld van de arbeider dat hij niet goed is opgeleid. Zeer waar. Het is niet zijn fout. Maar hoewel hij geen aandeel heeft in de fout, zal hij, als je dwaas genoeg bent om hem de hoogste macht in de staat te geven, er zelf het meest onder lijden.$$, 'inline'),
  ('7fa4b4b9-fa58-4377-9c37-bf43ee70bc56', 'e717feff-31d3-46d3-b474-ae8e4442055c', $$bron 6: prent van Jordaan 'Het arbeidsverbod voor de vrouw' (1912)$$,
   $$geschiedenis-havo-2021-iii-burgers-en-stoommachines-bron6.png$$,
   $$bron 6 In 1912 verschijnt in het Maandblad voor Vrouwenkiesrecht deze prent van tekenaar Jordaan met als titel Het arbeidsverbod voor de vrouw. De prent was een reactie op de nieuwe Arbeidswet, die in 1911 van kracht was geworden (de Arbeidswet beperkte onder andere de werktijd voor vrouwen in fabrieken en werkplaatsen tot tien uur per dag):
[Afbeelding] Prent: een vrouw met handboeien knielt bij een tafel met een brood; achter de tafel staat een man; naast de tafel ligt een kind.
Onder de bron staat: Minister Talma: Nu, vrouwtje, is het niet prettig dat de wet u in bescherming neemt en uw arbeidstijd verkort? Arbeidster: Excellentie, als wij, arbeidsters, zelf mede hadden geholpen om die wet te maken, zouden wij geen bescherming hebben in het leven geroepen, die ons ons brood ontneemt.
Toelichting: Op tafel ligt een brood met de tekst ''brood''. De man is minister Talma. Op de handboeien die de vrouw draagt, staat: arbeidswet. Naast de tafel ligt een kind.$$, 'inline'),
  ('5586023c-478b-4515-bde6-8c3e00dd68ed', '5126d4a6-1b8c-4c8a-8c7a-8249cb45aa9e', $$zes gebeurtenissen rond de Duitse munteenheid$$,
   $$geschiedenis-havo-2021-iii-duitsland-in-europa-context1.png$$,
   $$De volgende gebeurtenissen hebben te maken met veranderingen van de Duitse munteenheid en staan in willekeurige volgorde:
1 Als voorbereiding op de Duitse hereniging werd de Ostmark vervangen door de West-Duitse D-Mark. Ondanks het feit dat de Ostmark veel minder waard was, werd een wisselkoers vastgesteld van 1 : 1.
2 Met de ondertekening van het Verdrag van Maastricht werd mede vastgelegd dat in Duitsland een nieuwe, Europese munt ingevoerd zou worden.
3 Na de aanname van het Dawesplan werd een nieuwe munt uitgegeven: de rijksmark.
4 Na de machtsovername door de nazi''s werden munten uitgegeven waarop een adelaar stond die een hakenkruis droeg.
5 Na het uitroepen van de Duitse Republiek werden marken uitgegeven zonder keizerlijke kroon boven de adelaar.
6 Toen een nieuwe munt werd ingevoerd in de westelijke bezettingszones was dat de aanleiding voor de Blokkade van Berlijn.$$, 'inline'),
  ('c93d5d15-1bc0-456f-9205-3522f67e0068', '5126d4a6-1b8c-4c8a-8c7a-8249cb45aa9e', $$bron 8: poster van de Reichskolonialbund (1933)$$,
   $$geschiedenis-havo-2021-iii-duitsland-in-europa-bron8.png$$,
   $$bron 8 In 1933 publiceert de Duitse Reichskolonialbund deze poster:
[Afbeelding] Poster: een hakenkruisvlag en de vlag van het keizerrijk wapperen boven een wereldbol met Afrika en palmbomen; onderaan de tekst ''Auch hier liegt unser Lebensraum''.
Vertaling: Ook hier ligt onze leefruimte!
Toelichting: De achterste vlag is de vlag van het Duitse keizerrijk, de voorste vlag is de nazivlag. Duitsland en de gebieden die voor 1919 Duitse koloniën in Afrika waren, zijn op de kaart op de poster ingetekend.$$, 'inline'),
  ('9e72556a-a76a-45c2-b12d-51e8ea58e7c1', '5126d4a6-1b8c-4c8a-8c7a-8249cb45aa9e', $$bron 10: prent van Fritz Behrendt over de bouw van de Berlijnse Muur (1961)$$,
   $$geschiedenis-havo-2021-iii-duitsland-in-europa-bron10.png$$,
   $$bron 10 In september 1961 maakt Frits Behrendt deze prent:
[Afbeelding] Prent: DDR-soldaten metselen rij na rij muren met prikkeldraad; Ulbricht ligt tussen hen; aan de kant van de ''West Sektor'' staan Willy Brandt en een beer rustig toe te kijken.
Het onderschrift luidt: ''Snel Kameraden, nog een muur — het wemelt van volksvijanden en spionnen!''
Toelichting: ''Willy'' is Willy Brandt, de burgemeester van West-Berlijn. ''Ulbricht'' is Walter Ulbricht, de leider van de DDR. De beer is het symbool van Berlijn. West Sektor is de westelijke bezettingszone in Berlijn.$$, 'inline'),
  ('0b9ab107-de84-4002-99f0-951e773e84d1', 'c82a18ed-23c1-4280-8afc-0370ab84dba2', $$bron 11: pamflet van het Initiatiefcomité D'66 (1966)$$,
   $$geschiedenis-havo-2021-iii-nederland-1948-2008-bron11.png$$,
   $$bron 11 In 1966 publiceert het Initiatiefcomité D''66 het pamflet Appèl aan iedere Nederlander die ongerust is over de ernstige devaluatie van onze democratie. Daarin schrijft het comité onder meer:
De ideologieën van de huidige Nederlandse politieke partijen geven geen antwoord meer op de vragen die ons bezighouden. Velen zouden liever hun stem uitbrengen op grond van een visie op heden en toekomst dan op grond van politiek gezien verouderde beginselen.
De kiezers aanvaarden de bestaande politieke partijen steeds minder als uitdrukking van hun politieke wil. Daar komt bij dat de programma''s onderling zo weinig verschillen, dat zij de kiezers geen duidelijke keuzemogelijkheden meer bieden.$$, 'inline'),
  ('6ead12b3-7f68-4540-aca8-8e87a605fddb', 'c82a18ed-23c1-4280-8afc-0370ab84dba2', $$bron 12: poster van de kraakbeweging in Utrecht (1982)$$,
   $$geschiedenis-havo-2021-iii-nederland-1948-2008-bron12.png$$,
   $$bron 12 In 1982 verspreidt de kraakbeweging in Utrecht een poster met daarop de volgende tekst:
Wij blijven wonen! Met ontruiming bedreigd: nieuwegracht 155, kromme nieuwegracht 43 en biltstraat 164. Hand in hand willen overheid, spekulanten, justitie en politie kraakpanden ontruimen. Geld en smerige smoezen winnen het weer van wonen. Dit terwijl kraken de enige manier is om leegstand en woningnood echt effektief aan te pakken. Willen ze oorlog, krijgen ze oorlog.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('30a3dfc6-4198-4805-a954-f1936f70035b', 'ef11eb3d-fc70-4114-8238-ce1a42df5253', 1,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}, {"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}, {"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1978-2008)"}]'::jsonb,
   '["chronologie", "ontdekkingsreizen", "Franse Revolutie", "Wereldtentoonstelling", "Duitse bezetting", "multiculturele samenleving"]'::jsonb,
   $$Chronologisch ordenen van zes gebeurtenissen rond torens uit verschillende tijdvakken.$$,
   $$geschiedenis-havo-2021-iii-door-de-tijd-heen-vraag1.png$$, $$De volgende gebeurtenissen uit de geschiedenis waarin torens een rol hebben gespeeld, staan in willekeurige volgorde:
1 De aanslag op de torens van het World Trade Centre in New York verhevigde in Nederland de discussies over de multiculturele samenleving.
2 De bouw van de Eiffeltoren was onderdeel van de wereldtentoonstelling in Parijs, die als belangrijk doel had uitvindingen van het industriële tijdperk te laten zien.
3 De Toren van de Vrijheid in Parijs werd door een menigte afgebroken, omdat het bouwwerk onderdeel was van de gevangenis de Bastille, die als een symbool van het ancien régime werd beschouwd.
4 Portugese ontdekkingsreizigers, zoals Vasco da Gama, startten hun tochten bij de Toren van Belém.
5 Tijdens de Bezetting moest de naam van pretpark Julianatoren vlak bij Apeldoorn veranderd worden in Julia Toren, omdat verwijzingen naar levende leden van het koningshuis verboden waren.
6 Tijdens de bloeitijd van de Republiek gaven de Amsterdamse regenten voorrang aan een nieuw stadhuis, waardoor de geplande bouw van de toren van de Nieuwe Kerk niet doorging. 2p 1 Zet deze zes gebeurtenissen in de juiste chronologische volgorde, van vroeger naar later. Noteer alleen de nummers.$$, array[]::uuid[]),
  ('d28f9346-1f72-4079-8ec6-c4e015a5b95d', 'aefafd45-e8ca-4bef-88aa-bb1d83fe4e36', 2,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}]'::jsonb,
   '["Bartolomé de las Casas", "Europese expansie", "inheemse bevolking", "kerstening", "Spaanse verovering", "standpunt"]'::jsonb,
   $$Uitleggen hoe De las Casas met de beschreven gebeurtenis wetten ter bescherming en bekering van de inheemse bevolking bepleit.$$,
   $$geschiedenis-havo-2021-iii-ontdekkers-en-hervormers-vraag2.png$$, $$Gebruik bron 1. Een bewering: De las Casas wil met de beschreven gebeurtenis bereiken dat door het aannemen van wetten het gedrag van de Spanjaarden tegenover de inwoners van Amerika verandert. 4p 2 Toon dit aan door uit te leggen dat de beschreven gebeurtenis duidelijk maakt:
− dat wetten aangenomen moeten worden om de inheemse bevolking van Amerika te beschermen en
− dat door de aanname van zulke wetten de bekering van de inheemse bevolking van Amerika wordt bevorderd.$$, array['11897328-8f7e-45a0-a2e8-fde69bdf9bc8']::uuid[]),
  ('3d942087-c9cc-4b4f-a6bb-4ab81a94fbd9', 'aefafd45-e8ca-4bef-88aa-bb1d83fe4e36', 3,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Ontdekkers en hervormers — overig (1500-1600)"}]'::jsonb,
   '["Opstand", "Tachtigjarige Oorlog", "renaissance", "humanisme", "klassieke Oudheid", "kenmerkend aspect"]'::jsonb,
   $$Twee besluiten van het stadsbestuur van Woerden uit 1590 verklaren met verschillende kenmerkende aspecten van de zestiende eeuw.$$,
   $$geschiedenis-havo-2021-iii-ontdekkers-en-hervormers-vraag3.png$$, $$Het stadsbestuur van Woerden (nu in de provincie Utrecht) besloot in 1590:
1 om de vestingwerken van de stad te versterken en
2 om twee Romeinse molenstenen in het stadhuis tentoon te stellen die tijdens de werkzaamheden gevonden werden. 2p 3 Verklaar elk besluit met een ander kenmerkend aspect van de zestiende eeuw.$$, array[]::uuid[]),
  ('d0905fdf-ec57-4d44-a179-8773e3fa8495', 'aefafd45-e8ca-4bef-88aa-bb1d83fe4e36', 5,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}, {"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Regenten en vorsten — overig (1600-1700)"}, {"domain": "Het Britse Rijk (1585-1900)", "subdomain": "India als belangrijkste kolonie (1765-1885)"}]'::jsonb,
   '["Europese expansie", "Azteken", "Gouden Eeuw", "cultuurstelsel", "modern imperialisme", "kenmerkend aspect"]'::jsonb,
   $$Drie gegevens over de kleurstof karmijnrood koppelen aan verschillende kenmerkende aspecten.$$,
   $$geschiedenis-havo-2021-iii-ontdekkers-en-hervormers-vraag5.png$$, $$Drie gegevens over de geschiedenis van de kostbare kleurstof karmijnrood:
1 Spaanse veroveraars leerden van de Azteken in Amerika dat karmijnrood van luizen werd gemaakt en brachten in 1523 de kleurstof mee naar Spanje.
2 Rembrandt van Rijn gebruikte in 1665 voor zijn schilderij Het Joodse bruidje karmijnrood voor een deel van de jurk van de bruid.
3 Vanaf 1830 werden sommige boeren in Nederlands-Indië door de Nederlanders gedwongen om de luizen te kweken waar de kleurstof karmijnrood van gemaakt werd. 3p 5 Geef voor elk van de drie gegevens een ander kenmerkend aspect dat hierbij past.$$, array[]::uuid[]),
  ('d66f266a-eefe-4649-b1c6-f6c2dd1b2d72', 'aefafd45-e8ca-4bef-88aa-bb1d83fe4e36', 14,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}]'::jsonb,
   '["sociale kwestie", "arbeidersklasse", "woonomstandigheden", "bruikbaarheid", "representativiteit", "industrialisatie"]'::jsonb,
   $$De bruikbaarheid van een foto van Jacob Riis beoordelen voor twee onderzoeksvragen over Amerikaanse arbeiders in de negentiende eeuw.$$,
   $$geschiedenis-havo-2021-iii-ontdekkers-en-hervormers-vraag14.png$$, $$Gebruik bron 5. Stel, je doet onderzoek naar de woonomstandigheden van Amerikaanse arbeiders in de negentiende eeuw en je hebt twee onderzoeksvragen:
1 Wat waren de woonomstandigheden van de gemiddelde Amerikaanse arbeider in de negentiende eeuw?
2 Welke bijdrage leverde Riis aan de verbetering van de omstandigheden waarin Amerikaanse arbeiders leefden? Je vindt het boek van Riis en je komt tot de conclusie dat het boek voor onderzoeksvraag 1 minder bruikbare informatie en voor onderzoeksvraag 2 meer bruikbare informatie bevat. 2p 14 Ondersteun beide delen van je conclusie.$$, array['82c7b2a6-ded9-4862-8f4c-1bc64715d2c8']::uuid[]),
  ('7f794f93-b502-454b-a521-69aaf1d61802', '60071ab0-b960-4375-9998-9e25dd23c981', 7,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}, {"domain": "Het Britse Rijk (1585-1900)", "subdomain": "India als belangrijkste kolonie (1765-1885)"}]'::jsonb,
   '["industriële revolutie", "textielindustrie", "afzetmarkt", "huisnijverheid", "mechanisatie", "concurrentie"]'::jsonb,
   $$Uitleggen waarom Britse textielproducenten de concurrentiestrijd met Indiase producenten wonnen.$$,
   $$geschiedenis-havo-2021-iii-het-britse-rijk-vraag7.png$$, $$Gebruik bron 3. De Britse textielproducenten winnen de concurrentiestrijd met Indiase producenten, hoewel het Indiase textiel van hogere kwaliteit is. De bron biedt een verklaring voor deze ontwikkeling. 3p 7 Toon dit aan door:
− uit te leggen welke verklaring de bron geeft voor de export van Brits textiel naar het buitenland en
− zonder bron een verklaring te geven voor het feit dat de Indiase textielproducenten door hun manier van produceren de concurrentiestrijd met de Britse textielproducenten verliezen.$$, array['1059ad96-0463-41a9-9600-5a0270a2ca28']::uuid[]),
  ('be7213c1-3bad-4848-b21b-e7404e502cc5', '60071ab0-b960-4375-9998-9e25dd23c981', 8,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}]'::jsonb,
   '["Verlichting", "natuurrechten", "slavernij", "federale staat", "Amerikaanse grondwet", "argumenteren"]'::jsonb,
   $$Twee standpunten uit het Amerikaanse slavernijdebat van 1790 koppelen aan de Verlichting en de federale staatsvorm.$$,
   $$geschiedenis-havo-2021-iii-het-britse-rijk-vraag8.png$$, $$Twee beweringen:
− Standpunt 1 is gebaseerd op een ideaal van de Verlichting.
− Standpunt 2 past bij het feit dat de Verenigde Staten een federale staatsvorm hebben. 2p 8 Ondersteun beide beweringen met een argument.$$, array['a83585c2-6046-4a65-8b15-652ef82ee8a9']::uuid[]),
  ('93e2f6ca-3278-4366-a5e1-d8a00f64b172', '60071ab0-b960-4375-9998-9e25dd23c981', 9,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}]'::jsonb,
   '["slavernij", "zuidelijke staten", "plantage-economie", "federale staat", "Verenigde Staten", "standplaatsgebondenheid"]'::jsonb,
   $$Beredeneren of het standpunt dat het Congres slavernij niet kan verbieden vooral door noordelijke of zuidelijke staten werd gedeeld.$$,
   $$geschiedenis-havo-2021-iii-het-britse-rijk-vraag9.png$$, $$Gebruik opnieuw de standpunten uit vraag 8. 2p 9 Geef aan met een argument of standpunt 2 vooral gedeeld werd door vertegenwoordigers van de noordelijke of van de zuidelijke staten.$$, array['a83585c2-6046-4a65-8b15-652ef82ee8a9']::uuid[]),
  ('4664e12f-5b2f-424f-8e2d-710e3dd9522a', '60071ab0-b960-4375-9998-9e25dd23c981', 10,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}]'::jsonb,
   '["liberalisme", "liberale markteconomie", "vrijhandel", "ondernemers", "industriële revolutie", "illustratie"]'::jsonb,
   $$Uitleggen dat een anekdote over cholera in Sunderland (1831) de opkomst van een liberale markteconomie illustreert.$$,
   $$geschiedenis-havo-2021-iii-het-britse-rijk-vraag10.png$$, $$Een anekdote: In 1831 stelden artsen in de Britse havenstad Sunderland de eerste gevallen van cholera vast. Om verdere verspreiding te voorkomen bepaalde een gezondheidsraad die door de overheid was ingesteld (waar vooral artsen in zaten) dat alle schepen vijftien dagen in afzondering moesten worden gehouden. Twee weken later draaide de gezondheidsraad onder druk van ondernemers de maatregel terug, waarna de ziekte zich razendsnel verspreidde. Een bewering: Deze anekdote is illustratief voor de politiek-economische verhoudingen in Groot-Brittannië van dat moment. 3p 10 Ondersteun de bewering door:
− een reden te geven voor de houding van de ondernemers en
− uit te leggen dat de reactie van de gezondheidsraad paste bij het ontstaan van een liberale markteconomie in die periode.$$, array[]::uuid[]),
  ('df0a6719-5d59-4698-b25c-43c6bfe40fd9', '60071ab0-b960-4375-9998-9e25dd23c981', 12,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "India als belangrijkste kolonie (1765-1885)"}]'::jsonb,
   '["Brits bestuur in India", "indirect bestuur", "Brits rechtssysteem", "onderwijs", "Opstand van 1857", "kolonialisme"]'::jsonb,
   $$Uitleggen dat de oprichting van universiteiten in India in 1857 past bij de opzet van het Britse bestuur.$$,
   $$geschiedenis-havo-2021-iii-het-britse-rijk-vraag12.png$$, $$In 1857 stichtten de Britten in India universiteiten in Madras, Calcutta en Bombay. Op deze universiteiten kregen Indiërs les in het Britse rechtssysteem. 2p 12 Leg uit dat de oprichting van deze universiteiten past bij de opzet van het Britse bestuur in India.$$, array[]::uuid[]),
  ('d8452812-fdd3-4763-98de-44d9f46f9221', '60071ab0-b960-4375-9998-9e25dd23c981', 13,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "India als belangrijkste kolonie (1765-1885)"}, {"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}]'::jsonb,
   '["Suezkanaal", "modern imperialisme", "handelsroute", "Brits-Indië", "Royal Navy", "economisch belang"]'::jsonb,
   $$Uitleggen welke economische en machtspolitieke redenering de Britse regering volgde bij de aankoop van aandelen van het Suezkanaal (1875).$$,
   $$geschiedenis-havo-2021-iii-het-britse-rijk-vraag13.png$$, $$In 1875 kocht de Britse regering een groot deel van de aandelen van het Suezkanaal, waarmee het kanaal onder Britse controle kwam. De regering probeerde het parlement achter de aankoop van de aandelen te krijgen, met de argumenten dat controle over het Suezkanaal:
1 een economisch voordeel opleverde en
2 een versterking van het gezag over het Britse Rijk tot gevolg had. 2p 13 Geef voor beide argumenten aan welke redenering de regering hierbij volgde.$$, array[]::uuid[]),
  ('1438dfbf-fa4e-4538-8924-d224db942145', '23ccd0cb-5ceb-45d0-a6f1-d7c895df2f50', 4,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Regenten en vorsten — overig (1600-1700)"}]'::jsonb,
   '["wetenschappelijke revolutie", "wetenschappelijke methode", "empirisme", "pest", "zeventiende eeuw", "bron analyseren"]'::jsonb,
   $$Met verwijzing naar een tekst van Van Diemerbroeck uitleggen dat zijn onderzoek naar de pest past bij de wetenschappelijke revolutie.$$,
   $$geschiedenis-havo-2021-iii-regenten-en-vorsten-vraag4.png$$, $$Gebruik bron 2. Van Diemerbroeck beweert dat zijn onderzoek naar de pest beter is dan dat van zijn voorgangers. 3p 4 Verklaar zijn mening door:
− aan te geven welke oorzaak Van Diemerbroeck geeft voor het ontbreken van onderzoek naar de pest en
− met een verwijzing naar de bron aan te geven dat Van Diemerbroeck aansluit bij een werkwijze die past bij de zeventiende eeuw.$$, array['24a23bd0-0c97-4b73-aac4-ab434c8b373e']::uuid[]),
  ('9fdd8914-6659-40bc-80d9-3118f63305fd', 'd1962b2d-431d-4002-a86d-81a3dccd1cd1', 6,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Pruiken en revoluties — overig (1700-1800)"}]'::jsonb,
   '["verlicht absolutisme", "Frederik de Grote", "Pruisen", "Verlichting", "vooruitgangsgeloof", "ancien régime"]'::jsonb,
   $$Uitleggen dat het aardappelbevel van Frederik de Grote (1756) past bij zijn verlichte beleid.$$,
   $$geschiedenis-havo-2021-iii-pruiken-en-revoluties-vraag6.png$$, $$Een anekdote: Nadat Pruisen een aantal malen getroffen was door mislukte graanoogsten, vaardigde koning Frederik de Grote op 24 maart 1756 het zogenaamde Kartoffelbefehl (aardappelbevel) uit, omdat hij ervan overtuigd was dat met het verbouwen van aardappels hongersnood kon worden voorkomen. Magistraten en beambten moesten zijn onderdanen kennis laten maken met het nut van de aardappelplant en ervoor zorgen dat deze plant op iedere beschikbare plek werd verbouwd. Bewering: Het Kartoffelbefehl past bij het Verlichte beleid van Frederik de Grote.
2p 6 Leg de bewering uit.$$, array[]::uuid[]),
  ('03737fe2-2b15-4ad5-a67e-2d7a27fe921f', 'b97e7a7d-188a-43b5-a00a-b70f29451728', 16,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Wereldoorlogen — overig (1900-1950)"}]'::jsonb,
   '["Eerste Wereldoorlog", "propaganda", "pamflet", "moreel", "totale oorlog", "boodschap"]'::jsonb,
   $$Uitleggen welke boodschap over het Duitse leger een Brits pamflet uit 1918 overbrengt en wat de Britten ermee wilden bereiken.$$,
   $$geschiedenis-havo-2021-iii-tijd-van-wereldoorlogen-vraag16.png$$, $$Gebruik bron 1. Bewering: Dit pamflet gaat over Duitsland in 1918 en is een voorbeeld van Britse propaganda. 3p 16 Licht dit toe door:
− aan te geven met een verwijzing naar de onderste helft van de bron, welke boodschap over de toestand van het Duitse leger de Britten willen overbrengen en
− aan te geven wat de Britten met het pamflet willen bereiken.$$, array['f3b7be70-c9aa-4dd2-b925-8dc934ea262c']::uuid[]),
  ('53281f1b-ae22-4113-a156-9e171b74d901', 'b97e7a7d-188a-43b5-a00a-b70f29451728', 21,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Wereldoorlogen — overig (1900-1950)"}, {"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Duitsland en de Koude Oorlog (1945-1961)"}]'::jsonb,
   '["Tweede Wereldoorlog", "Sovjet-Unie", "propaganda", "Koude Oorlog", "bondgenootschap", "Verenigde Staten"]'::jsonb,
   $$Uitleggen waarom foto's van een Sovjetsluipschutter met Eleanor Roosevelt in 1942 wel en vijf jaar later niet in Russische kranten pasten.$$,
   $$geschiedenis-havo-2021-iii-tijd-van-wereldoorlogen-vraag21.png$$, $$In 1942 werden in Washington D.C foto''s gemaakt van een ontmoeting tussen Ljoedmila Pavlitsjenko, een beroemde sluipschutter in het Sovjetleger, en Eleanor Roosevelt, de vrouw van de Amerikaanse president. Bewering: Deze foto''s konden tijdens de Tweede Wereldoorlog in Russische kranten gepubliceerd worden, maar vijf jaar later was dat niet meer toegestaan. 3p 21 Ondersteun de bewering door:
− aan te geven welke propagandaboodschap de Sovjetregering tijdens de Tweede Wereldoorlog met de foto''s kon overbrengen en
− uit te leggen dat de Sovjetregering publicatie vijf jaar later om politieke redenen niet wenselijk vond.$$, array[]::uuid[]),
  ('96483db9-0488-473f-a8a6-20b087aa471d', 'b97e7a7d-188a-43b5-a00a-b70f29451728', 22,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Wereldoorlogen — overig (1900-1950)"}, {"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Opkomst nationaalsocialisme en gevolgen (1918-1945)"}]'::jsonb,
   '["totale oorlog", "burgerbevolking", "Tweede Wereldoorlog", "bombardementen", "illustratie", "kenmerkend aspect"]'::jsonb,
   $$Met een kenmerkend aspect uitleggen dat een foto van schuilende burgers in Nijmegen (1944) de gevolgen van moderne oorlogvoering illustreert.$$,
   $$geschiedenis-havo-2021-iii-tijd-van-wereldoorlogen-vraag22.png$$, $$Gebruik bron 9. Deze foto kan gebruikt worden als illustratie van de gevolgen van de manier van oorlogvoering in de eerste helft van de twintigste eeuw. 2p 22 Leg uit met behulp van een kenmerkend aspect dat de foto illustratief voor die gevolgen is.$$, array['32b5918f-a5aa-4b1c-938b-2706c8441cdd']::uuid[]),
  ('c0f1712e-699f-4c30-9cda-3d9821b6d86a', 'e717feff-31d3-46d3-b474-ae8e4442055c', 11,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}]'::jsonb,
   '["democratisering", "kiesrecht", "chartisme", "arbeidersbeweging", "emancipatie", "liberalisme"]'::jsonb,
   $$Met verwijzingen naar een betoog van Macaulay (1842) uitleggen dat hij chaos vreest door democratisering en arbeidersemancipatie.$$,
   $$geschiedenis-havo-2021-iii-burgers-en-stoommachines-vraag11.png$$, $$Gebruik bron 4. Bewering: Macaulay vreest voor chaos door:
− de voortschrijdende democratisering en
− de invloed van de opkomende emancipatiebeweging van de arbeiders. 4p 11 Geef voor beide onderdelen van de bewering een argument, telkens met een verwijzing naar de bron.$$, array['facf2958-70a5-4953-87e2-6a183dcf83c8']::uuid[]),
  ('7888b3b4-91f0-439c-90dc-4bce48079567', 'e717feff-31d3-46d3-b474-ae8e4442055c', 15,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}]'::jsonb,
   '["feminisme", "eerste feministische golf", "vrouwenkiesrecht", "Arbeidswet", "sociale wetgeving", "spotprent"]'::jsonb,
   $$Uitleggen welke kritiek de tekenaar Jordaan in een prent uit 1912 geeft op de gevolgen van de Arbeidswet.$$,
   $$geschiedenis-havo-2021-iii-burgers-en-stoommachines-vraag15.png$$, $$Gebruik bron 6. Jordaan geeft in de prent kritiek weer op de gevolgen van de Arbeidswet uit 1911. 2p 15 Leg uit welke kritiek Jordaan weergeeft.$$, array['7fa4b4b9-fa58-4377-9c37-bf43ee70bc56']::uuid[]),
  ('c18543e1-5907-4f60-83be-94a5b678bcb0', '5126d4a6-1b8c-4c8a-8c7a-8249cb45aa9e', 17,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Opkomst nationaalsocialisme en gevolgen (1918-1945)"}]'::jsonb,
   '["Verdrag van Versailles", "oorlogsschuld", "herstelbetalingen", "Eerste Wereldoorlog", "artikel 231", "redeneren"]'::jsonb,
   $$Uitleggen dat het schuldartikel in het Verdrag van Versailles andere bepalingen voor Duitsland rechtvaardigde.$$,
   $$geschiedenis-havo-2021-iii-duitsland-in-europa-vraag17.png$$, $$In het Verdrag van Versailles stond in artikel 231 dat Duitsland schuldig was aan het uitbreken van de Eerste Wereldoorlog. Een redenering: Artikel 231 was bedoeld om uit te leggen waarom andere bepalingen voor Duitsland in het Verdrag van Versailles opgenomen werden. 2p 17 Licht deze redenering toe aan de hand van een andere bepaling voor Duitsland in het Verdrag van Versailles.$$, array[]::uuid[]),
  ('8116e83c-ed2a-4d22-a3f0-43a7400bbfda', '5126d4a6-1b8c-4c8a-8c7a-8249cb45aa9e', 18,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Opkomst nationaalsocialisme en gevolgen (1918-1945)"}, {"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Duitsland en de Koude Oorlog (1945-1961)"}, {"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Hereniging en Europese integratie (1961-1991)"}]'::jsonb,
   '["chronologie", "Republiek van Weimar", "Dawesplan", "Blokkade van Berlijn", "Duitse hereniging", "Verdrag van Maastricht"]'::jsonb,
   $$Chronologisch ordenen van zes gebeurtenissen rond de Duitse munteenheid in de twintigste eeuw.$$,
   $$geschiedenis-havo-2021-iii-duitsland-in-europa-vraag18.png$$, $$2p 18 Zet deze zes gebeurtenissen in de juiste chronologische volgorde, van vroeger naar later. Noteer alleen de nummers.$$, array['5586023c-478b-4515-bde6-8c3e00dd68ed']::uuid[]),
  ('60f243c8-1cd0-4bd5-ad2d-3bff6a0c3ce5', '5126d4a6-1b8c-4c8a-8c7a-8249cb45aa9e', 19,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Hereniging en Europese integratie (1961-1991)"}]'::jsonb,
   '["Duitse hereniging", "D-Mark", "Kohl", "DDR", "integratie voormalige DDR", "politiek doel"]'::jsonb,
   $$Uitleggen welk politiek doel werd nagestreefd met de wisselkoers van 1 : 1 tussen Ostmark en D-Mark bij de hereniging.$$,
   $$geschiedenis-havo-2021-iii-duitsland-in-europa-vraag19.png$$, $$Gebruik gebeurtenis 1 uit vraag 18. 2p 19 Leg uit welk politiek doel met deze wisselkoers van de Ostmark en de D-Mark werd nagestreefd.$$, array['5586023c-478b-4515-bde6-8c3e00dd68ed']::uuid[]),
  ('0c1df8b8-240f-464f-9f19-b0628075bb0e', '5126d4a6-1b8c-4c8a-8c7a-8249cb45aa9e', 20,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Opkomst nationaalsocialisme en gevolgen (1918-1945)"}]'::jsonb,
   '["nationaalsocialisme", "Lebensraum", "koloniën", "propaganda", "conservatieven", "buitenlands beleid"]'::jsonb,
   $$Uitleggen dat een koloniale poster uit 1933 afwijkt van het nazibeleid maar wel conservatieve aanhangers kon werven.$$,
   $$geschiedenis-havo-2021-iii-duitsland-in-europa-vraag20.png$$, $$Gebruik bron 1. Bewering: De boodschap die de Reichskolonialbund met deze poster wil overbrengen, wijkt af van de kern van het buitenlandse beleid van de nazi''s, maar kan gebruikt worden om aanhangers te werven onder conservatieve Duitsers. 4p 20 Leg beide onderdelen van de bewering uit, steeds met een aparte verwijzing naar de bron.$$, array['c93d5d15-1bc0-456f-9205-3522f67e0068']::uuid[]),
  ('193e5c2e-f0d3-4941-b027-8310f2cb3962', '5126d4a6-1b8c-4c8a-8c7a-8249cb45aa9e', 23,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Duitsland en de Koude Oorlog (1945-1961)"}]'::jsonb,
   '["Berlijnse Muur", "Ulbricht", "DDR", "Koude Oorlog", "spotprent", "propaganda"]'::jsonb,
   $$Met verwijzingen naar een prent uit 1961 aantonen dat de tekenaar zich keert tegen de DDR-uitleg van de bouw van de Muur.$$,
   $$geschiedenis-havo-2021-iii-duitsland-in-europa-vraag23.png$$, $$Gebruik bron 10. De bouw van de Berlijnse Muur wordt door de regering van de DDR uitgelegd als een manier om de burgers van de DDR te beschermen tegen westers imperialisme. Een interpretatie: Met deze bron keert de tekenaar zich tegen deze uitleg. 3p 23 Ondersteun de interpretatie met twee verwijzingen naar de bron.$$, array['9e72556a-a76a-45c2-b12d-51e8ea58e7c1']::uuid[]),
  ('feafee72-0cf7-4adb-b382-5de299bbdcdf', '5126d4a6-1b8c-4c8a-8c7a-8249cb45aa9e', 26,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Hereniging en Europese integratie (1961-1991)"}, {"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Duitsland en de Koude Oorlog (1945-1961)"}]'::jsonb,
   '["BRD", "DDR", "8 mei 1945", "Duitse deling", "herinneringscultuur", "standplaatsgebondenheid"]'::jsonb,
   $$Het verschil in visie op 8 mei 1945 in de BRD en de DDR verklaren vanuit het politieke beleid in 1977.$$,
   $$geschiedenis-havo-2021-iii-duitsland-in-europa-vraag26.png$$, $$De Duitse historicus Alfred Grosser zei in 1977 over 8 mei 1945, de dag dat Duitsland capituleerde, dat deze dag in de BRD werd gezien als een nationale ramp, als het begin van de Duitse deling. "Maar", zei hij, "als je naar de DDR gaat, dan zie je dat aan hele schoolklassen wordt verteld dat 8 mei 1945 een bevrijdingsdag was." 2p 26 Verklaar het beschreven verschil in de Duitse visies op 8 mei 1945 vanuit het politieke beleid in beide landen in 1977.$$, array[]::uuid[]),
  ('acfd4f72-2a30-433f-a48d-a7a91aee593e', 'c82a18ed-23c1-4280-8afc-0370ab84dba2', 24,
   '[{"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1948-1978)"}]'::jsonb,
   '["consumptiemaatschappij", "tweede feministische golf", "positie van vrouwen", "rolpatroon", "advertentie", "welvaartsgroei"]'::jsonb,
   $$Beoordelen of een stofzuigeradvertentie uit 1963 de opkomst van de consumptiemaatschappij en de vrouwenemancipatie ondersteunt.$$,
   $$geschiedenis-havo-2021-iii-nederland-1948-2008-vraag24.png$$, $$In 1963 verscheen in het vrouwenblad Margriet een advertentie voor het ''Tankmodel'', een nieuw model stofzuiger van Philips. In een fotostrip werd het verhaal verteld van een vrouw die problemen heeft met haar oude model stofzuiger. Met haar man schaft zij het ''Tankmodel'' aan, waarna zij weer probleemloos kan stofzuigen. In de tijd dat de advertentie geplaatst werd, deden zich in Nederland twee veranderingen voor:
1 Nederland werd een consumptiemaatschappij.
2 De emancipatie van de vrouw kwam op gang. 4p 24 Geef voor beide veranderingen aan of deze met de advertentie ondersteund kunnen worden of niet.$$, array[]::uuid[]),
